class Solution {
public:
    int rob(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) return nums[0];
        return max(robLinear(nums, 0, n - 2), robLinear(nums, 1, n - 1));
    }
private:
    int robLinear(const vector<int>& nums, int l, int r) {
        long long prev = 0, curr = 0;
        for (int i = l; i <= r; ++i) {
            long long newCurr = max(curr, prev + nums[i]);
            prev = curr;
            curr = newCurr;
        }
        return static_cast<int>(curr);
    }
};
